      'import sys\n\n\ndef main():\n    lines = sys.stdin.read().split("\\n")\n    rows, cols = map(int, lines[0].split())\n    grid = [list(lines[1 + i].strip()) for i in range(rows)]\n    areas = largest = 0\n    for i in range(rows):\n        for j in range(cols):\n            if grid[i][j] != ".":\n                continue\n            areas += 1\n            size = 0\n            grid[i][j] = "#"\n            stack = [(i, j)]\n            while stack:\n                a, b = stack.pop()\n                size += 1\n                for x, y in ((a + 1, b), (a - 1, b), (a, b + 1), (a, b - 1)):\n                    if 0 <= x < rows and 0 <= y < cols and grid[x][y] == ".":\n                        grid[x][y] = "#"\n                        stack.append((x, y))\n            largest = max(largest, size)\n    print(areas, largest)\n\n\nmain()\n',
