    reference:
      'import heapq\nimport sys\n\n\ndef main():\n    data = list(map(int, sys.stdin.read().split()))\n    n, m = data[0], data[1]\n    after = [[] for _ in range(n + 1)]\n    waiting = [0] * (n + 1)\n    for i in range(m):\n        a, b = data[2 + 2 * i], data[3 + 2 * i]\n        after[a].append(b)\n        waiting[b] += 1\n    ready = [t for t in range(1, n + 1) if waiting[t] == 0]\n    heapq.heapify(ready)\n    order = []\n    while ready:\n        t = heapq.heappop(ready)\n        order.append(t)\n        for nxt in after[t]:\n            waiting[nxt] -= 1\n            if waiting[nxt] == 0:\n                heapq.heappush(ready, nxt)\n    print(" ".join(map(str, order)) if len(order) == n else "IMPOSSIBLE")\n\n\nmain()\n',
